// News-image 2026-11-18 entry: writes the 18-November world-news collage PNG.
// Deterministic: same bytes every run, stdlib only, no network calls.
// Layout: navy header (date 18 November 2026), 8 story cards across
// 5 regions, ALSO footer + sources line. Stories verified from
// Wikipedia Portal:Current_events/2026_November_18.
// Run: mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const dir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(dir, { recursive: true });
const B64 = "";
writeFileSync(join(dir, 'entry.png'), Buffer.from(B64, 'base64'));
